/* ============================================================
   Data Mart MultiPizza - script completo (esquema + datos + vista)
   Base: DB_DATAMART_MULTIPIZZA
   Fuente: padron transaccional MultiPizza (Lima, 2026)

   Instrucciones:
   1) Ejecutar en SQL Server (SSMS o sqlcmd).
   2) Requiere la instancia localhost\SQLEXPRESS (o ajustar la
      conexion en Power BI: Inicio > Transformar datos > Origen).
   3) Si la base ya existe, elimine DB_DATAMART_MULTIPIZZA antes
      de ejecutar este script.
   ============================================================ */
SET NOCOUNT ON;
GO

IF DB_ID('DB_DATAMART_MULTIPIZZA') IS NULL
    CREATE DATABASE DB_DATAMART_MULTIPIZZA;
GO
USE DB_DATAMART_MULTIPIZZA;
GO

/* ---------- Tablas ---------- */
CREATE TABLE dbo.DIM_PRODUCTO (
    id_producto     VARCHAR(18)  NOT NULL CONSTRAINT PK_DIM_PRODUCTO PRIMARY KEY,
    nombre_producto VARCHAR(100) NOT NULL,
    categoria       VARCHAR(50)  NOT NULL
);
GO
CREATE TABLE dbo.DIM_LOCAL (
    id_local     VARCHAR(18)  NOT NULL CONSTRAINT PK_DIM_LOCAL PRIMARY KEY,
    nombre_local VARCHAR(50)  NOT NULL,
    direccion    VARCHAR(100) NULL
);
GO
CREATE TABLE dbo.DIM_TIEMPO (
    id_tiempo  VARCHAR(18) NOT NULL CONSTRAINT PK_DIM_TIEMPO PRIMARY KEY,
    fecha      DATE        NOT NULL,
    anio       INT         NOT NULL,
    mes        VARCHAR(20) NOT NULL,
    dia        INT         NOT NULL,
    dia_semana VARCHAR(20) NOT NULL,
    turno      VARCHAR(20) NULL,
    hora       TIME(7)     NULL,
    mes_numero INT         NULL,
    trimestre  INT         NULL,
    semana     INT         NULL
);
GO
CREATE TABLE dbo.DIM_PRESENTACION (
    id_presentacion     VARCHAR(18)  NOT NULL CONSTRAINT PK_DIM_PRESENTACION PRIMARY KEY,
    nombre_presentacion VARCHAR(50)  NOT NULL,
    precio_base         DECIMAL(10,2) NOT NULL,
    id_producto         VARCHAR(18)  NULL
);
GO
CREATE TABLE dbo.FACT_VENTA (
    id_venta        VARCHAR(18)   NOT NULL,
    id_tiempo       VARCHAR(18)   NOT NULL,
    id_local        VARCHAR(18)   NOT NULL,
    id_producto     VARCHAR(18)   NOT NULL,
    id_presentacion VARCHAR(18)   NOT NULL,
    cantidad        INT           NOT NULL,
    precio_unitario DECIMAL(10,2) NOT NULL,
    subtotal        DECIMAL(10,2) NOT NULL,
    id_detalle      INT           NOT NULL CONSTRAINT PK_FACT_VENTA PRIMARY KEY,
    hora            TIME(7)       NULL
);
GO

