/* ---------- Restricciones e indices ---------- */
ALTER TABLE dbo.DIM_PRESENTACION ADD CONSTRAINT FK_PRES_PRODUCTO
    FOREIGN KEY (id_producto) REFERENCES dbo.DIM_PRODUCTO(id_producto);
ALTER TABLE dbo.FACT_VENTA ADD CONSTRAINT FK_FACT_TIEMPO
    FOREIGN KEY (id_tiempo) REFERENCES dbo.DIM_TIEMPO(id_tiempo);
ALTER TABLE dbo.FACT_VENTA ADD CONSTRAINT FK_FACT_LOCAL
    FOREIGN KEY (id_local) REFERENCES dbo.DIM_LOCAL(id_local);
ALTER TABLE dbo.FACT_VENTA ADD CONSTRAINT FK_FACT_PRODUCTO
    FOREIGN KEY (id_producto) REFERENCES dbo.DIM_PRODUCTO(id_producto);
ALTER TABLE dbo.FACT_VENTA ADD CONSTRAINT FK_FACT_PRESENTACION
    FOREIGN KEY (id_presentacion) REFERENCES dbo.DIM_PRESENTACION(id_presentacion);
ALTER TABLE dbo.FACT_VENTA ADD CONSTRAINT UQ_FACT_VENTA_PRES UNIQUE (id_venta, id_presentacion);
ALTER TABLE dbo.FACT_VENTA ADD CONSTRAINT CK_FACT_CANTIDAD CHECK (cantidad > 0);
ALTER TABLE dbo.FACT_VENTA ADD CONSTRAINT CK_FACT_SUBTOTAL CHECK (subtotal = cantidad * precio_unitario);
GO
CREATE INDEX IX_DIM_TIEMPO_FECHA ON dbo.DIM_TIEMPO(fecha);
CREATE INDEX IX_PRES_PRODUCTO ON dbo.DIM_PRESENTACION(id_producto);
CREATE INDEX IX_FACT_TIEMPO ON dbo.FACT_VENTA(id_tiempo);
CREATE INDEX IX_FACT_LOCAL ON dbo.FACT_VENTA(id_local);
CREATE INDEX IX_FACT_PRODUCTO ON dbo.FACT_VENTA(id_producto);
CREATE INDEX IX_FACT_PRESENTACION ON dbo.FACT_VENTA(id_presentacion);
CREATE INDEX IX_FACT_VENTA ON dbo.FACT_VENTA(id_venta);
GO

/* ---------- Vista para KPIs ---------- */
CREATE OR ALTER VIEW dbo.vw_Ventas AS
SELECT f.id_detalle, f.id_venta, t.fecha, t.anio, t.mes_numero, t.mes,
       t.trimestre, t.semana, t.dia, t.dia_semana,
       CAST(f.hora AS TIME(0)) AS hora,
       CASE WHEN DATEPART(hour, f.hora) < 16 THEN 'Almuerzo (12-15)'
            WHEN DATEPART(hour, f.hora) < 19 THEN 'Tarde (16-18)'
            ELSE 'Noche (19-21)' END AS turno,
       l.id_local, l.nombre_local,
       p.id_producto, p.nombre_producto, p.categoria,
       pr.id_presentacion, pr.nombre_presentacion,
       f.cantidad, f.precio_unitario, f.subtotal
FROM dbo.FACT_VENTA f
JOIN dbo.DIM_TIEMPO t        ON t.id_tiempo = f.id_tiempo
JOIN dbo.DIM_LOCAL l         ON l.id_local = f.id_local
JOIN dbo.DIM_PRODUCTO p      ON p.id_producto = f.id_producto
JOIN dbo.DIM_PRESENTACION pr ON pr.id_presentacion = f.id_presentacion;
GO

/* ---------- Verificacion ---------- */
SELECT 'DIM_TIEMPO' tabla, COUNT(*) filas FROM dbo.DIM_TIEMPO
UNION ALL SELECT 'DIM_LOCAL', COUNT(*) FROM dbo.DIM_LOCAL
UNION ALL SELECT 'DIM_PRODUCTO', COUNT(*) FROM dbo.DIM_PRODUCTO
UNION ALL SELECT 'DIM_PRESENTACION', COUNT(*) FROM dbo.DIM_PRESENTACION
UNION ALL SELECT 'FACT_VENTA', COUNT(*) FROM dbo.FACT_VENTA;
SELECT ROUND(SUM(subtotal),2) AS ventas_netas, COUNT(DISTINCT id_venta) AS tickets,
       SUM(cantidad) AS unidades FROM dbo.FACT_VENTA;
GO
